 1→import { computed, inject, Injectable } from '@angular/core';
 2→import { TUI_DARK_MODE } from '@taiga-ui/core';
 3→
 4→/**
 5→ * Clean API surface decoupling consumers from the Taiga UI TUI_DARK_MODE token.
 6→ * Serves as the single extension point for future theme features
 7→ * (e.g., localStorage persistence, system preference detection).
 8→ */
 9→@Injectable({ providedIn: 'root' })
10→export class ThemeService {
11→  private readonly darkMode = inject(TUI_DARK_MODE);
12→
13→  readonly isDarkMode = this.darkMode.asReadonly();
14→
15→  readonly themeName = computed(() => (this.darkMode() ? 'dark' : 'light'));
16→
17→  toggleTheme(): void {
18→    this.darkMode.set(!this.darkMode());
19→  }
20→}
21→

 1→import { TestBed } from '@angular/core/testing';
 2→import { WritableSignal, signal } from '@angular/core';
 3→import { TUI_DARK_MODE } from '@taiga-ui/core';
 4→import { ThemeService } from './theme.service';
 5→
 6→describe('ThemeService', () => {
 7→  let service: ThemeService;
 8→  let darkModeSignal: WritableSignal<boolean>;
 9→
10→  beforeEach(() => {
11→    darkModeSignal = signal(false);
12→
13→    TestBed.configureTestingModule({
14→      providers: [
15→        ThemeService,
16→        { provide: TUI_DARK_MODE, useValue: darkModeSignal },
17→      ],
18→    });
19→    service = TestBed.inject(ThemeService);
20→  });
21→
22→  it('should be created', () => {
23→    expect(service).toBeTruthy();
24→  });
25→
26→  it('should report light mode when dark mode signal is false', () => {
27→    expect(service.isDarkMode()).toBe(false);
28→  });
29→
30→  it('should report dark mode when dark mode signal is true', () => {
31→    darkModeSignal.set(true);
32→    expect(service.isDarkMode()).toBe(true);
33→  });
34→
35→  it('should toggle from light to dark', () => {
36→    service.toggleTheme();
37→    expect(service.isDarkMode()).toBe(true);
38→  });
39→
40→  it('should toggle from dark to light', () => {
41→    darkModeSignal.set(true);
42→    service.toggleTheme();
43→    expect(service.isDarkMode()).toBe(false);
44→  });
45→
46→  it('should expose the theme name as a computed signal', () => {
47→    expect(service.themeName()).toBe('light');
48→    darkModeSignal.set(true);
49→    expect(service.themeName()).toBe('dark');
50→  });
