// Verify note counts per string
const CHROMATIC = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
const NATURAL = new Set(['C','D','E','F','G','A','B']);
const OPEN = {1:'E',2:'B',3:'G',4:'D',5:'A',6:'E'};
let total = 0;
for (let s = 1; s <= 6; s++) {
  const start = CHROMATIC.indexOf(OPEN[s]);
  let count = 0;
  for (let f = 0; f <= 15; f++) {
    if (NATURAL.has(CHROMATIC[(start+f)%12])) count++;
  }
  console.log('String', s, ':', count, 'natural notes');
  total += count;
}
console.log('Total:', total);
