 5→
 6→const LANGUAGES = ['NL', 'DE', 'EN'] as const;
 7→const VALID_LOCALES = ['en', 'nl', 'de'] as const;
 8→
 9→const LOCALE_TO_LANGUAGE: Record<string, string> = {
10→  en: 'EN',
11→  nl: 'NL',
12→  de: 'DE',
13→};
14→
15→/**
16→ * Injectable function for navigating to a URL.
17→ * Abstracted to allow easy testing without jsdom location restrictions.
18→ */
19→export type NavigateFn = (url: string) => void;
20→
21→export const NAVIGATE_FN = new InjectionToken<NavigateFn>('NavigateFn', {
22→  providedIn: 'root',
23→  factory: () => {
24→    const doc = inject(DOCUMENT);
25→    return (url: string) => {
26→      const window = doc.defaultView;
27→      if (window) {
28→        window.location.href = url;
29→      }
30→    };
31→  },
32→});
