 1→export interface FretNote {
 2→  string: number; // 1-6 (1 = high E, 6 = low E)
 3→  fret: number;   // 0-15 (0 = open)
 4→  note: string;   // 'C' | 'D' | 'E' | 'F' | 'G' | 'A' | 'B'
 5→  x: number;      // x position on fretboard image (%)
 6→  y: number;      // y position on fretboard image (%)
 7→}
 8→
 9→/**
10→ * Chromatic scale used to derive natural notes per string.
11→ * Standard guitar tuning: E-A-D-G-B-E (string 6 to 1).
12→ */
13→const CHROMATIC_SCALE = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'] as const;
14→
15→const NATURAL_NOTES = new Set(['C', 'D', 'E', 'F', 'G', 'A', 'B']);
16→
17→/** Open string notes in standard tuning, indexed by string number (1-6). */
18→const OPEN_STRING_NOTES: Record<number, string> = {
19→  1: 'E', // high E
20→  2: 'B',
21→  3: 'G',
22→  4: 'D',
23→  5: 'A',
24→  6: 'E', // low E
25→};
26→
27→/**
28→ * Y-position (%) for each string on the fretboard image.
29→ * String 6 (low E) is at the bottom, string 1 (high E) at the top.
30→ */
31→const STRING_Y_POSITIONS: Record<number, number> = {
32→  1: 8,
33→  2: 25,
34→  3: 42,
35→  4: 58,
36→  5: 75,
37→  6: 92,
38→};
39→
40→/**
41→ * X-position (%) for each fret on the fretboard image.
42→ * Fret 0 (open/nut) is on the far left, fret 15 on the far right.
43→ * Positions approximate the midpoint of each fret space.
44→ */
45→function fretXPosition(fret: number): number {
46→  if (fret === 0) {
47→    return 1.5;
48→  }
49→  // Frets 1-15 distributed across roughly 6% to 97% of the image width
50→  // Real fretboard spacing decreases toward higher frets, but we use
51→  // approximate linear spacing since these will be fine-tuned later.
52→  return 3 + (fret / 15) * 94;
53→}
54→
55→function generateFretNotes(): FretNote[] {
56→  const notes: FretNote[] = [];
57→
58→  for (let guitarString = 1; guitarString <= 6; guitarString++) {
59→    const openNote = OPEN_STRING_NOTES[guitarString];
60→    const startIndex = CHROMATIC_SCALE.indexOf(openNote as typeof CHROMATIC_SCALE[number]);
61→
62→    for (let fret = 0; fret <= 15; fret++) {
63→      const noteIndex = (startIndex + fret) % 12;
64→      const noteName = CHROMATIC_SCALE[noteIndex];
65→
66→      if (NATURAL_NOTES.has(noteName)) {
67→        notes.push({
68→          string: guitarString,
69→          fret,
70→          note: noteName,
71→          x: fretXPosition(fret),
72→          y: STRING_Y_POSITIONS[guitarString],
73→        });
74→      }
75→    }
76→  }
77→
78→  return notes;
79→}
